#!/bin/bash
source "$(dirname "$0")/lib.sh"
export X="Si aucun résultat n'apparaît, essayez un mot plus court ou plus simple (« disque » plutôt que « partition »). Chaque résultat renvoie vers la page complète."
j "Rechercher, c'est retrouver un sujet sans parcourir toutes les pages : vous tapez un mot dans la case de recherche, DMP cherche ce mot dans toutes ses pages et vous montre les passages concernés. Pourquoi : gagner du temps quand on cherche une information précise." "Utilisez la case de recherche de la page (à gauche, sous « Ce qu'on voit »)." "Recherche prête" "recherche dans /api/*"
